class AgePolicy:
    # Interface: every age policy must implement is_allowed
    def is_allowed(self, age):
        raise NotImplementedError


class MinimumAgePolicy(AgePolicy):
    def __init__(self, minimum_age):
        self.minimum_age = minimum_age

    def is_allowed(self, age):
        return age >= self.minimum_age


class AgeValidator:
    def __init__(self, policy):
        self.policy = policy

    def validate(self, age):
        return self.policy.is_allowed(age)


if __name__ == "__main__":
    validator = AgeValidator(MinimumAgePolicy(18))
    print(validator.validate(20))  # True
    print(validator.validate(15))  # False

