codes.cpp:
#include <iostream>

class AgePolicy {
public:
    virtual bool is_allowed(int age) const = 0;
    virtual ~AgePolicy() = default;
};

class MinimumAgePolicy : public AgePolicy {
private:
    int minimum_age;

public:
    explicit MinimumAgePolicy(int minimum_age) : minimum_age(minimum_age) {}

    bool is_allowed(int age) const override {
        return age >= minimum_age;
    }
};

class AgeValidator {
private:
    AgePolicy* policy;

public:
    explicit AgeValidator(AgePolicy* policy) : policy(policy) {}

    bool validate(int age) const {
        return policy->is_allowed(age);
    }
};

int main() {
    MinimumAgePolicy minimumAgePolicy(18);
    AgeValidator validator(&minimumAgePolicy);
    std::cout << std::boolalpha << validator.validate(20) << std::endl; // true
    std::cout << std::boolalpha << validator.validate(15) << std::endl; // false
    return 0;
}

